import{_ as a,o as t,c as i,a6 as n}from"./chunks/framework.CKIbuWFA.js";const u=JSON.parse('{"title":"TikTools 4.2.1-rc.1 candidate record","description":"","frontmatter":{"title":"TikTools 4.2.1-rc.1 candidate record","docId":"releases.4.2.1-rc.1","translationKey":"releases.4.2.1-rc.1","locale":"en","audience":"user","featureStatus":"experimental","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"f2b9e975511584a1a6156af8326d7603d73be54f10c97d7e46ed385def4755f6","translationRevision":"f2b9e975511584a1a6156af8326d7603d73be54f10c97d7e46ed385def4755f6","order":10},"headers":[],"relativePath":"en/releases/4.2.1-rc.1.md","filePath":"en/releases/4.2.1-rc.1.md","lastUpdated":1794591482000}'),s={name:"en/releases/4.2.1-rc.1.md"};function r(o,e,d,l,c,h){return t(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="tiktools-421-rc1" tabindex="-1">TikTools 4.2.1-rc.1 <a class="header-anchor" href="#tiktools-421-rc1" aria-label="Permalink to &quot;TikTools 4.2.1-rc.1 {#tiktools-421-rc1}&quot;">​</a></h1><h2 id="goal-status-and-prerequisites" tabindex="-1">Goal, status and prerequisites <a class="header-anchor" href="#goal-status-and-prerequisites" aria-label="Permalink to &quot;Goal, status and prerequisites {#goal-status-and-prerequisites}&quot;">​</a></h2><p>Use this historical candidate record to reproduce the Cloud recovery, Teams and Linux AppImage problems investigated for RC1. It describes the application baseline <code>338495a9</code> and a separate backend baseline <code>6a69c99</code>. These notes do not establish the current availability of RC1 downloads. Check the <a href="https://github.com/nglmercer/TikTools-app/releases" target="_blank" rel="noreferrer">published release assets</a> before choosing an installer.</p><p>The recorded candidate used locally built Linux AppImage, DEB and portable packages while Actions was disabled. It did not include a newly built Windows installer. Keep a backup and an isolated copy of the affected profile for migration testing. Collaboration and Cloud section recovery remain experimental.</p><h2 id="changes-in-this-candidate" tabindex="-1">Changes in this candidate <a class="header-anchor" href="#changes-in-this-candidate" aria-label="Permalink to &quot;Changes in this candidate {#changes-in-this-candidate}&quot;">​</a></h2><ul><li>Settings retains account/session and diagnostics; Plugins owns its catalog, search, Changes and installation actions. Templates and profiles stay in Automations.</li><li>The shared Changes panel distinguishes a failed comparison from a successful empty result. The Plugins section sends its own selections/settings while retaining other queues and cached downloads.</li><li>Migration tolerates a missing implicit bundled-plugin directory, keeps explicitly configured paths strict and identifies missing package IDs for reviewed repair. Pending edits and conflicts are retained.</li><li>Teams distinguishes enrolling this PC as a host from selecting a host on another PC. Nickname invitations bind the selected recipient, with host approval still required.</li><li>Optional guided help follows setup state. Linux packaging includes WebKit helpers, GStreamer plugins and the scanner for subsequent media checks.</li></ul><h2 id="reproduce-and-inspect-the-expected-result" tabindex="-1">Reproduce and inspect the expected result <a class="header-anchor" href="#reproduce-and-inspect-the-expected-result" aria-label="Permalink to &quot;Reproduce and inspect the expected result {#reproduce-and-inspect-the-expected-result}&quot;">​</a></h2><ol><li>Record the displayed version and operating system. Open Plugins → Changes and keep the exact error and request ID if loading fails.</li><li>In the copied profile, preview migration and review the exact missing package IDs before repair. Preview again afterward; pending edits and conflicts should still be present.</li><li>In Teams, enroll the current PC before testing its Start control. Selecting another PC&#39;s host should not authorize starting this one.</li><li>Check AppImage startup and then audio/video separately. Reaching the frontend alone does not establish successful media playback.</li></ol><p>Nickname search and recipient-bound invitations require backend <code>6a69c99</code> and migration <code>20261113000001_remote_invitation_recipients.sql</code>. Installing this candidate does not deploy that backend.</p><h2 id="recovery-and-evidence-limits" tabindex="-1">Recovery and evidence limits <a class="header-anchor" href="#recovery-and-evidence-limits" aria-label="Permalink to &quot;Recovery and evidence limits {#recovery-and-evidence-limits}&quot;">​</a></h2><p>If a comparison fails, retain the native reason and retry through the supported panel. Do not delete pending state or infer successful migration from a compatibility check. Collect version, action and redacted diagnostic details using the <a href="./../user/preferences/troubleshooting.html">troubleshooting guide</a>.</p><p>The original record reports frontend, sync-engine, recipient-isolation and two-host native/relay checks at its baseline. Those dated checks are not fresh production validation. The historical SQLite lock holder was not identified. At RC1, Variables and Overlay Cloud adapters were unfinished, and Automations compared a local reference. Read <a href="./4.2.1-rc.3.html">later candidate notes</a> and the <a href="./../user/cloud/changes.html">current Changes guide</a> for subsequent scope.</p><p>The <a href="https://github.com/nglmercer/TikTools-app/blob/80c5cb1fbfa45eaeb1c086c71320a15e565d8541/docs/RELEASE-4.2.1-rc.1.md" target="_blank" rel="noreferrer">original release record</a> is retained as dated evidence. Return to the <a href="./">release index</a>.</p>',13)])])}const g=a(s,[["render",r]]);export{u as __pageData,g as default};
